import assert from 'node:assert/strict'
import { execFileSync, spawn } from 'node:child_process'
import { existsSync, rmSync, writeFileSync } from 'node:fs'

export const sleep = ms => new Promise(r => setTimeout(r, ms))
export const js = value => JSON.stringify(value)

export class Cdp {
  constructor(url) { this.url=url; this.ws=null; this.id=1; this.pending=new Map(); this.requests=[] }
  async connect() {
    this.ws = new WebSocket(this.url)
    await new Promise((r,j)=>{const t=setTimeout(()=>j(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);r()},{once:true});this.ws.addEventListener('error',()=>j(new Error('ws error')),{once:true})})
    this.ws.addEventListener('message', e => { const m=JSON.parse(e.data); if(m.method==='Network.requestWillBeSent') this.requests.push({url:m.params.request.url,method:m.params.request.method}); const p=m.id?this.pending.get(m.id):null; if(!p)return; this.pending.delete(m.id); m.error?p.j(new Error(m.error.message)):p.r(m.result) })
    for(const x of ['Page.enable','Runtime.enable','DOM.enable','CSS.enable','Network.enable','Accessibility.enable']) await this.send(x)
    await this.send('Emulation.setLocaleOverride',{locale:'ko-KR'})
    await this.send('Page.addScriptToEvaluateOnNewDocument',{source:`(()=>{const nativeFetch=window.fetch.bind(window);const nativeBeacon=navigator.sendBeacon?.bind(navigator);window.__qaBlockedAnalytics=0;window.__qaBlockedWrites=0;window.fetch=(input,init={})=>{const url=typeof input==='string'?input:(input&&input.url)||'';const method=String(init.method||(input&&input.method)||'GET').toUpperCase();if(url.includes('/functions/v1/decision-intake')){window.__qaBlockedAnalytics+=1;return Promise.resolve(new Response(null,{status:204}))}if(url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(method)){window.__qaBlockedWrites+=1;return Promise.resolve(new Response(null,{status:204}))}return nativeFetch(input,init)};if(nativeBeacon){navigator.sendBeacon=(url,data)=>{const u=String(url||'');if(u.includes('/functions/v1/decision-intake')){window.__qaBlockedAnalytics+=1;return true}return nativeBeacon(url,data)}}})();`})
  }
  send(method,params={}){const id=this.id++;return new Promise((r,j)=>{this.pending.set(id,{r,j});this.ws.send(JSON.stringify({id,method,params}))})}
  async eval(expression){const x=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(x.exceptionDetails)throw new Error(x.exceptionDetails.exception?.description||x.exceptionDetails.text);return x.result?.value}
  async wait(expression,label,ms=45000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}
  async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root');await this.eval('document.fonts?.ready');await sleep(220)}
  async shot(path){await this.eval('document.fonts?.ready');await sleep(80);const x=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(x.data,'base64'))}
  async fonts(selector){const {root}=await this.send('DOM.getDocument',{depth:1});const {nodeId}=await this.send('DOM.querySelector',{nodeId:root.nodeId,selector});assert.ok(nodeId,`font node missing ${selector}`);return (await this.send('CSS.getPlatformFontsForNode',{nodeId})).fonts??[]}
  async axName(selector){const {root}=await this.send('DOM.getDocument',{depth:1});const {nodeId}=await this.send('DOM.querySelector',{nodeId:root.nodeId,selector});if(!nodeId)return null;const t=await this.send('Accessibility.getPartialAXTree',{nodeId,fetchRelatives:false});const n=t.nodes?.find(v=>v.role?.value==='button')??t.nodes?.[0];return{name:n?.name?.value??null,role:n?.role?.value??null,ignored:n?.ignored??null}}
  close(){try{this.ws?.close()}catch{}}
}

export async function launch(width,height){const chrome='/usr/bin/google-chrome';assert.ok(existsSync(chrome),'Chrome unavailable');const port=9810+(process.pid%100)+(width%17),dir=`/tmp/mode-${width}-${height}-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(chrome,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--disable-cache',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json(),p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p){const c=new Cdp(p.webSocketDebuggerUrl);await c.connect();await c.send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true,screenWidth:width,screenHeight:height});await c.send('Emulation.setUserAgentOverride',{userAgent:'Mozilla/5.0 (Linux; Android 16; Mobile) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Mobile Safari/537.36',acceptLanguage:'ko-KR,ko;q=0.9,en;q=0.8',platform:'Android'});return{c,proc,dir,version:execFileSync(chrome,['--version'],{encoding:'utf8'}).trim()}}}catch{}await sleep(100)}throw new Error('Chrome launch timeout')}

export async function info(c,selector,text=null,index=0){return c.eval(`(()=>{const norm=v=>(v||'').replace(/\\s+/g,' ').trim(),all=[...document.querySelectorAll(${js(selector)})],list=${text===null?'all':`all.filter(n=>norm(n.textContent)===${js(text)})`},n=list[${index}];if(!n)return null;const s=getComputedStyle(n),r=n.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=r.width>0&&r.height>0&&x>=0&&x<innerWidth&&y>=0&&y<innerHeight?document.elementFromPoint(x,y):null;return{text:norm(n.textContent),ariaLabel:n.getAttribute('aria-label'),ariaCurrent:n.getAttribute('aria-current'),className:n.className,rect:[r.left,r.top,r.width,r.height],rendered:s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0,inViewport:r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth,centerHit:Boolean(h&&(h===n||n.contains(h))),hit:h?.className||h?.tagName||null,disabled:Boolean(n.disabled)}})()`)}

export async function pointer(c,selector,text=null,index=0){const ok=await c.eval(`(()=>{const norm=v=>(v||'').replace(/\\s+/g,' ').trim(),all=[...document.querySelectorAll(${js(selector)})],list=${text===null?'all':`all.filter(n=>norm(n.textContent)===${js(text)})`},n=list[${index}];if(!n)return false;n.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});return true})()`);assert.equal(ok,true,`missing ${selector} ${text??''}`);await sleep(100);const m=await info(c,selector,text,index);assert.ok(m?.rendered&&m.inViewport&&m.centerHit&&!m.disabled,`unavailable ${JSON.stringify(m)}`);const [l,t,w,h]=m.rect,x=l+w/2,y=t+h/2;await c.send('Input.dispatchMouseEvent',{type:'mouseMoved',x,y});await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x,y,button:'left',clickCount:1});await sleep(200);return{...m,x,y}}

export async function typeText(c,selector,value){await pointer(c,selector);await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'a',code:'KeyA',modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'a',code:'KeyA',modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Backspace',code:'Backspace'});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'Backspace',code:'Backspace'});await c.send('Input.insertText',{text:value});await sleep(220)}

export async function browserBack(c){const h=await c.send('Page.getNavigationHistory');assert.ok(h.currentIndex>0,'no browser back entry');await c.send('Page.navigateToHistoryEntry',{entryId:h.entries[h.currentIndex-1].id});await sleep(280);return{from:h.currentIndex,to:h.currentIndex-1}}

export async function topbar(c){const brand=await info(c,'.research-brand');const buttons=await c.eval(`(()=>[...document.querySelectorAll('.mode-nav .mode-button')].map(n=>{const s=getComputedStyle(n),r=n.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=r.width&&r.height&&x>=0&&x<innerWidth&&y>=0&&y<innerHeight?document.elementFromPoint(x,y):null;return{text:n.textContent.trim(),className:n.className,ariaCurrent:n.getAttribute('aria-current'),rect:[r.left,r.top,r.width,r.height],rendered:s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0,inViewport:r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth,centerHit:Boolean(h&&(h===n||n.contains(h)))}}))()`);const headings=await c.eval(`(()=>[...document.querySelectorAll('h1,.mode-intro strong,.research-pane-heading strong,.switch-step-header h1,.switch-find-hero h1')].filter(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0}).slice(0,4).map(n=>n.textContent.trim()))()`);return{brand,brandAx:await c.axName('.research-brand'),buttons,active:buttons.find(b=>String(b.className).includes('is-active'))??null,headings}}

export async function screen(c){return c.eval(`(()=>{if(document.querySelector('.home-shell'))return'home';if(document.querySelector('.detail-stage'))return'detail';if(document.querySelector('.compare-stage'))return'compare';if(document.querySelector('.switch-find-stage,.switch-step-layout,.switch-results-stage'))return'switch';if(document.querySelector('.lookup-input'))return'lookup';if(document.querySelector('.research-workspace'))return'explore';return'unknown'})()`)}

export async function network(c){const sentAnalytics=c.requests.filter(r=>r.url.includes('/functions/v1/decision-intake')),sentWrites=c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(r.method));return{blocked:await c.eval(`({analytics:window.__qaBlockedAnalytics||0,writes:window.__qaBlockedWrites||0})`),sentAnalytics,sentWrites,publicReads:c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&r.method==='GET').length}}
